CREATE TABLE IF NOT EXISTS device_inventory ( device_id text PRIMARY KEY, tenant_id text NOT NULL, user_id text NOT NULL, hostname text NOT NULL, os text NOT NULL, os_version text NOT NULL DEFAULT '', agent_version text NOT NULL, device_trust_level text NOT NULL CHECK (device_trust_level IN ('managed', 'unmanaged', 'unknown')), policy_bundle_id text NOT NULL, policy_bundle_version text NOT NULL, status text NOT NULL CHECK (status IN ('registered', 'healthy', 'degraded', 'offline', 'revoked')), registered_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE INDEX IF NOT EXISTS device_inventory_tenant_status_idx ON device_inventory (tenant_id, status, last_seen_at DESC);
CREATE INDEX IF NOT EXISTS device_inventory_tenant_user_idx ON device_inventory (tenant_id, user_id, device_id);
